//! "This PC" sign-in data: Apple's anisette generated by the web version of
//! iCloud for Windows (AOSKit) on this computer, instead of a shared online
//! server. A small 32-bit helper (built from helper/anisette_helper.cs and
//! embedded here) talks to AOSKit, because AOSKit is 32-bit only.
//!
//! This is the public technique AltServer for Windows uses; Sideloadly's
//! public changelog describes its own equivalent ("iTunes Anisette").

use isideload::anisette::{
    AnisetteClientInfo, AnisetteData, AnisetteDataResponse, AnisetteProvider,
};
use isideload::auth::grandslam::GrandSlam;
use rootcause::Report;
use std::path::PathBuf;
use std::sync::Arc;

static HELPER: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/anisette-helper.exe"));

/// How this sign-in identity describes itself to Apple. A modern macOS is
/// used because Apple IDs with Advanced Data Protection refuse sign-ins from
/// macOS versions older than 13.1.
pub const CLIENT_INFO: &str = "<MacBookPro15,1> <macOS;13.6.4;22G513> <com.apple.AuthKit/1 (com.apple.akd/1.0)>";
pub const USER_AGENT: &str = "akd/1.0 CFNetwork/1410.0.3 Darwin/22.6.0";
/// Routing info value used with locally generated anisette (as AltServer does).
const ROUTING_INFO: &str = "17106176";

fn data_dir() -> PathBuf {
    std::env::var_os("APPDATA")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
        .join("ipabazooka")
}

fn aoskit_path() -> PathBuf {
    let common = std::env::var_os("CommonProgramFiles(x86)")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(r"C:\Program Files (x86)\Common Files"));
    common.join("Apple").join("Internet Services").join("AOSKit.dll")
}

/// Why "This PC" sign-in data can't be used, in plain words (None if it can).
pub fn unavailable_reason() -> Option<String> {
    if HELPER.is_empty() {
        Some("this copy of ipabazooka was built without the iCloud helper".into())
    } else if !aoskit_path().exists() {
        Some("the web version of iCloud for Windows isn't installed (the Microsoft Store version can't be used)".into())
    } else {
        None
    }
}

/// Writes the embedded helper next to the app's data (only when changed).
fn helper_path() -> Result<PathBuf, String> {
    let dir = data_dir();
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    let path = dir.join("anisette-helper.exe");
    let same = std::fs::metadata(&path).map(|m| m.len() == HELPER.len() as u64).unwrap_or(false)
        && std::fs::read(&path).map(|b| b == HELPER).unwrap_or(false);
    if !same {
        std::fs::write(&path, HELPER).map_err(|e| format!("couldn't write the helper: {e}"))?;
    }
    Ok(path)
}

/// A stable device ID for this PC in Apple's UUID style. Prefers `preferred`
/// (this Windows install's machine id, from the helper) so the device the
/// sign-in data claims to be stays the same every run; otherwise keeps a
/// random one saved in the app's data folder.
fn device_id(preferred: Option<&str>) -> String {
    if let Some(p) = preferred {
        let p = p.trim().to_uppercase();
        if p.len() == 36 {
            return p;
        }
    }
    let path = data_dir().join("local-device-id.txt");
    if let Ok(s) = std::fs::read_to_string(&path) {
        let s = s.trim().to_string();
        if s.len() == 36 {
            return s;
        }
    }
    let b: [u8; 16] = rand::random();
    let id = format!(
        "{:02X}{:02X}{:02X}{:02X}-{:02X}{:02X}-{:02X}{:02X}-{:02X}{:02X}-{:02X}{:02X}{:02X}{:02X}{:02X}{:02X}",
        b[0], b[1], b[2], b[3], b[4], b[5], (b[6] & 0x0F) | 0x40, b[7], (b[8] & 0x3F) | 0x80, b[9], b[10], b[11], b[12], b[13], b[14], b[15]
    );
    let _ = std::fs::create_dir_all(data_dir());
    let _ = std::fs::write(&path, &id);
    id
}

pub struct LocalHeaders {
    pub otp: String,
    pub machine_id: String,
    pub icloud: String,
    /// this Windows install's machine id (may be empty on older iCloud versions)
    pub deviceid: String,
}

/// Runs the helper and returns this PC's current anisette values.
pub fn fetch() -> Result<LocalHeaders, String> {
    if let Some(why) = unavailable_reason() {
        return Err(format!("Local anisette unavailable: {why}"));
    }
    let exe = helper_path()?;
    let mut cmd = std::process::Command::new(&exe);
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x0800_0000); // CREATE_NO_WINDOW
    }
    let out = cmd.output().map_err(|e| format!("Local anisette helper couldn't start: {e}"))?;
    let text = String::from_utf8_lossy(&out.stdout);
    let line = text.lines().rev().find(|l| l.trim_start().starts_with('{')).unwrap_or("").trim();
    let v: serde_json::Value = serde_json::from_str(line).map_err(|_| {
        format!(
            "Local anisette helper gave no answer (exit {:?}): {}",
            out.status.code(),
            String::from_utf8_lossy(&out.stderr).lines().last().unwrap_or("")
        )
    })?;
    if let Some(e) = v.get("error").and_then(|e| e.as_str()) {
        return Err(format!("Local anisette (iCloud for Windows): {e}"));
    }
    let get = |k: &str| v.get(k).and_then(|x| x.as_str()).unwrap_or("").to_string();
    let h = LocalHeaders { otp: get("md"), machine_id: get("mdm"), icloud: get("icloud"), deviceid: get("deviceid") };
    if h.otp.is_empty() || h.machine_id.is_empty() {
        return Err("Local anisette (iCloud for Windows) returned incomplete data".into());
    }
    Ok(h)
}

/// isideload anisette provider backed by this PC's iCloud for Windows.
pub struct LocalAnisetteProvider;

impl LocalAnisetteProvider {
    pub fn new() -> Self {
        LocalAnisetteProvider
    }
}

#[async_trait::async_trait]
impl AnisetteProvider for LocalAnisetteProvider {
    async fn get_anisette_data(&self) -> Result<AnisetteDataResponse, Report> {
        let h = tokio::task::spawn_blocking(fetch)
            .await
            .map_err(|e| rootcause::report!("Local anisette task failed: {e}"))?
            .map_err(|e| rootcause::report!("{e}"))?;
        // Tie the device the data claims to be to this Windows install's own
        // machine id, so every piece of the sign-in data is about one device.
        let dev = device_id(Some(&h.deviceid));
        crate::write_log_line(
            "DBG ",
            &format!("Local anisette from iCloud for Windows ({}); device id {}", h.icloud, dev),
        );
        use sha2::Digest;
        let local_user = sha2::Sha256::digest(dev.as_bytes())
            .iter()
            .map(|b| format!("{b:02X}"))
            .collect::<String>();
        Ok(AnisetteDataResponse::Data(AnisetteData::from_parts(
            h.machine_id,
            h.otp,
            ROUTING_INFO.to_string(),
            CLIENT_INFO.to_string(),
            dev,
            local_user,
        )))
    }

    async fn get_client_info(&self) -> Result<AnisetteClientInfo, Report> {
        Ok(AnisetteClientInfo { client_info: CLIENT_INFO.to_string(), user_agent: USER_AGENT.to_string() })
    }

    async fn provision(&mut self, _gs: &Arc<GrandSlam>, _force_recheck: bool) -> Result<(), Report> {
        // iCloud for Windows keeps this PC provisioned itself.
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    /// Runs the real helper when iCloud for Windows (web) is installed here;
    /// on machines without it, checks that the reason is reported instead.
    #[test]
    fn local_anisette_works_or_explains_why_not() {
        match super::unavailable_reason() {
            Some(why) => assert!(!why.is_empty()),
            None => {
                let h = super::fetch().expect("helper should return sign-in data");
                assert!(h.otp.len() >= 20, "one-time password looks too short");
                assert!(h.machine_id.len() >= 40, "machine id looks too short");
                // the device id must stay the same between runs
                assert_eq!(super::device_id(Some(&h.deviceid)), super::device_id(Some(&h.deviceid)));
            }
        }
    }
}
